<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:600">Implement insertion sort</span><br>
<span id="demoNarration" style="display:block;margin:0;font-size:10px;max-width:260px"></span>
<button onclick="prevStep()">◀</button> <span id="stepLabel">Step 1 of 4</span> <button onclick="nextStep()">▶</button><br>
<span style="font-weight:600">Code sample</span><br>
<button id="sampleTab">Correct</button> <button id="buggyTab">Buggy</button> <button id="starterTab">Starter</button><br>
<label>Initial array <input id="insertionSortCodeInput" value="5, 2, 4, 6, 1, 3" style="width:100%;box-sizing:border-box"></label>
<textarea id="insertionSortCodeCode" spellcheck="false">function insertionSort() {
  markSortedPrefix(1);

  for (let j = 2; j &lt;= n(); j++) {
    let i = j;
    markKey(i);
    note("Insert A[" + j + "] into the sorted prefix.");

    while (i &gt; 1 &amp;&amp; compare(i - 1, i)) {
      i = shift(i);
      markKey(i);
    }

    markSortedPrefix(j);
  }

  note("The entire array is sorted.");
}</textarea>
<button id="runBtn">Run</button> <span id="runStatus">not run</span><br>
<button id="firstFrameBtn">|◀</button> <button id="prevFrameBtn">◀</button> <button id="playBtn">Play</button> <button id="nextFrameBtn">▶</button>
<label>Speed <input id="speedInput" type="range" min="0.5" max="4" step="0.5" value="1"></label>
<span id="frameCounter">0 of 0</span><br>
<span id="frameCaption" style="display:block;font-size:11px;line-height:1.25;max-width:280px"></span>
<textarea id="traceLog" readonly style="min-height:90px" aria-label="Trace log"></textarea>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 900, 430);

var sampleCode = 'function insertionSort() {\n' +
'  markSortedPrefix(1);\n\n' +
'  for (let j = 2; j <= n(); j++) {\n' +
'    let i = j;\n' +
'    markKey(i);\n' +
'    note("Insert A[" + j + "] into the sorted prefix.");\n\n' +
'    while (i > 1 && compare(i - 1, i)) {\n' +
'      i = shift(i);\n' +
'      markKey(i);\n' +
'    }\n\n' +
'    markSortedPrefix(j);\n' +
'  }\n\n' +
'  note("The entire array is sorted.");\n' +
'}';

var buggyCode = 'function insertionSort() {\n' +
'  markSortedPrefix(1);\n\n' +
'  for (let j = 2; j <= n(); j++) {\n' +
'    let i = j;\n' +
'    markKey(i);\n\n' +
'    // Bug: the comparison is reversed, so large keys move left instead of small keys.\n' +
'    while (i > 1 && compare(i, i - 1)) {\n' +
'      i = shift(i);\n' +
'      markKey(i);\n' +
'    }\n\n' +
'    markSortedPrefix(j);\n' +
'  }\n' +
'}';

var starterCode = 'function insertionSort() {\n' +
'  markSortedPrefix(1);\n\n' +
'  for (let j = 2; j <= n(); j++) {\n' +
'    let i = j;\n' +
'    markKey(i);\n' +
'    // Compare left neighbor with the key.\n' +
'    // If the left neighbor is larger, shift the key left.\n' +
'    // When the key stops, grow the sorted prefix.\n' +
'  }\n' +
'}';

var frames = [];
var currentFrame = 0;
var playing = false;
var playTimer = null;
var runSerial = 0;
var activeWorker = null;
var demoIndex = 0;

var demoSteps = [
  {
    title: 'Start with one sorted item',
    narration: 'The first element alone is already sorted. The algorithm begins at position 2 and treats that value as the key to insert into the sorted prefix on its left.'
  },
  {
    title: 'Move a small key left',
    narration: 'When the key is smaller than its left neighbor, compare returns true and shift moves the key one position left. This recreates the motion shown by the curved arrows.'
  },
  {
    title: 'Stop when the prefix is ordered',
    narration: 'When the key reaches the front or is no longer smaller than its left neighbor, the pass ends and the gray sorted prefix grows by one cell.'
  },
  {
    title: 'Finish with the whole array sorted',
    narration: 'After the last key has been inserted, every position belongs to the sorted prefix and the array is [1, 2, 3, 4, 5, 6].'
  }
];

function makeInitialFrame() {
  return {
    kind: 'demo',
    state: {
      array: [5, 2, 4, 6, 1, 3],
      sortedK: 1,
      keyIndex: 2,
      compare: [1, 2],
      arrows: [{ from: 2, to: 1 }],
      input: [5, 2, 4, 6, 1, 3]
    },
    indices: [1, 2],
    message: 'Panel (a): insert key 2 into the one-item sorted prefix.'
  };
}

frames = [makeInitialFrame()];
drawFrame(frames[0]);
updateUiForFrame();

function panelLabelFor(frame) {
  if (!frame || !frame.state) return '(a)';
  var s = frame.state;
  var a = s.array || [];
  var key = s.keyIndex ? a[s.keyIndex - 1] : null;
  if (!s.keyIndex && a.join(',') === '1,2,3,4,5,6') return '(f)';
  if (key === 2) return '(a)';
  if (key === 4) return '(b)';
  if (key === 6) return '(c)';
  if (key === 1) return '(d)';
  if (key === 3) return '(e)';
  if (s.sortedK >= 6) return '(f)';
  return '(a)';
}

function drawArrow(g, from, to, color, width, opacity, longArc) {
  var cellW = 90, cellH = 70, x0 = 190, y0 = 120;
  var sx = x0 + (from - 0.5) * cellW;
  var ex = x0 + (to - 0.5) * cellW;
  var y = y0 + cellH + 4;
  var depth = longArc ? 88 : 64;
  var path = 'M ' + sx + ' ' + y + ' C ' + sx + ' ' + (y + depth) + ' ' + ex + ' ' + (y + depth) + ' ' + ex + ' ' + y;
  g.path(path).fill('none').stroke({ color: color, width: width, linecap: 'round' }).opacity(opacity);
  g.polygon([[ex, y - 4], [ex - 12, y + 20], [ex + 12, y + 20]])
    .fill(color).stroke('none').opacity(opacity);
}

function addHover(el, title, body) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(title, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup(title, body); });
}

function drawFrame(frame) {
  draw.clear();
  var s = frame.state || {};
  var arr = s.array || [5, 2, 4, 6, 1, 3];
  var cellW = 90, cellH = 70, x0 = 190, y0 = 120;
  var fontFam = 'Times New Roman, Times, serif';
  var gray = '#c8c8c8';
  var wrongSet = {};
  var hiSet = {};
  var i;

  if (frame.kind === 'wrong' || frame.kind === 'error') {
    for (i = 0; i < (frame.indices || []).length; i++) wrongSet[frame.indices[i]] = true;
  }
  for (i = 0; i < (s.compare || frame.indices || []).length; i++) hiSet[(s.compare || frame.indices || [])[i]] = true;

  draw.rect(900, 430).fill('#ffffff');

  draw.text(panelLabelFor(frame))
    .font({ family: fontFam, size: 54, anchor: 'middle' })
    .move(88, 140)
    .fill('#000');

  for (i = 1; i <= arr.length; i++) {
    draw.text(String(i))
      .font({ family: fontFam, size: 42, anchor: 'middle' })
      .center(x0 + (i - 0.5) * cellW, y0 - 24)
      .fill('#000');
  }

  var arrows = s.arrows || [];
  if (arrows.length > 0) {
    for (i = 0; i < arrows.length; i++) {
      drawArrow(draw, arrows[i].from, arrows[i].to, '#8f8f8f', 2.5, 0.9, false);
    }
    drawArrow(draw, arrows[0].from, arrows[arrows.length - 1].to, '#000000', 2.6, 1, true);
  }

  var cells = draw.group();
  for (i = 1; i <= arr.length; i++) {
    var fill = '#ffffff';
    if (!(s.sortedK >= arr.length && !s.keyIndex) && i <= (s.sortedK || 0)) fill = gray;
    if (s.keyIndex === i) fill = '#000000';

    var r = cells.rect(cellW, cellH).move(x0 + (i - 1) * cellW, y0)
      .fill(fill).stroke({ color: '#000000', width: 2 });
    addHover(
      r,
      'A[' + i + '] = ' + arr[i - 1],
      (s.keyIndex === i ? 'This black cell is the current key being inserted.' :
        (i <= (s.sortedK || 0) ? 'This gray cell belongs to the already-sorted prefix.' :
          'This white cell is still in the unsorted part of the array.'))
    );

    cells.text(String(arr[i - 1]))
      .font({ family: fontFam, size: 54, anchor: 'middle' })
      .center(x0 + (i - 0.5) * cellW, y0 + cellH / 2 + 2)
      .fill(s.keyIndex === i ? '#ffffff' : '#000000');
  }

  for (i = 1; i <= arr.length; i++) {
    if (hiSet[i]) {
      draw.rect(cellW - 5, cellH - 5).move(x0 + (i - 1) * cellW + 2.5, y0 + 2.5)
        .fill('none').stroke({ color: '#f0a000', width: 4 });
    }
    if (wrongSet[i]) {
      draw.rect(cellW - 11, cellH - 11).move(x0 + (i - 1) * cellW + 5.5, y0 + 5.5)
        .fill('none').stroke({ color: '#d62728', width: 5 });
    }
  }

  var caption = frame.message || '';
  var capBg = draw.rect(650, 44).radius(6).center(450, 342).fill({ color: '#ffffff', opacity: 0.88 }).stroke({ color: '#dddddd', width: 1 });
  var cap = draw.text(caption).font({ family: 'Arial, sans-serif', size: 18, anchor: 'middle' })
    .center(450, 342).fill('#222');
  cap.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  addHover(capBg, 'Trace message', 'This line describes the operation that produced the current replay frame.');
}

function updateUiForFrame() {
  var f = frames[currentFrame] || frames[0];
  document.getElementById('frameCounter').textContent = frames.length ? ((currentFrame + 1) + ' of ' + frames.length) : '0 of 0';
  document.getElementById('frameCaption').textContent = f ? f.message : '';
  var log = '';
  for (var i = 0; i < frames.length; i++) {
    log += (i === currentFrame ? '▶ ' : '  ') + (i + 1) + '. ' + (frames[i].message || frames[i].kind) + '\n';
  }
  document.getElementById('traceLog').value = log;
}

function showFrame(idx) {
  if (!frames.length) return;
  currentFrame = Math.max(0, Math.min(frames.length - 1, idx));
  drawFrame(frames[currentFrame]);
  updateUiForFrame();
}

function stopPlayback() {
  playing = false;
  if (playTimer) clearTimeout(playTimer);
  playTimer = null;
  document.getElementById('playBtn').textContent = 'Play';
}

function playbackTick() {
  if (!playing) return;
  if (currentFrame >= frames.length - 1) {
    stopPlayback();
    return;
  }
  showFrame(currentFrame + 1);
  var speed = +document.getElementById('speedInput').value || 1;
  playTimer = setTimeout(playbackTick, 650 / speed);
}

function togglePlayback() {
  if (playing) {
    stopPlayback();
  } else {
    playing = true;
    document.getElementById('playBtn').textContent = 'Pause';
    playbackTick();
  }
}

function parseInputArray(src) {
  var nums = String(src).split(',').map(function (p) { return Number(p.trim()); });
  if (nums.length !== 6 || nums.some(function (v) { return !isFinite(v); })) {
    throw new Error('Enter exactly six numeric values, separated by commas.');
  }
  return nums;
}

function findDemoFrameIndex(step) {
  if (!frames.length) return 0;
  var i, s, a;
  if (step === 0) {
    for (i = 0; i < frames.length; i++) {
      s = frames[i].state || {}; a = s.array || [];
      if (s.keyIndex === 2 && a.join(',') === '5,2,4,6,1,3') return i;
    }
    return 0;
  }
  if (step === 1) {
    for (i = 0; i < frames.length; i++) {
      if (frames[i].kind === 'shift') return i;
    }
    return Math.min(3, frames.length - 1);
  }
  if (step === 2) {
    for (i = 0; i < frames.length; i++) {
      s = frames[i].state || {}; a = s.array || [];
      if (s.sortedK >= 3 && !s.keyIndex && a.slice(0, 3).join(',') === '2,4,5') return i;
    }
    return Math.floor(frames.length / 2);
  }
  for (i = frames.length - 1; i >= 0; i--) {
    s = frames[i].state || {}; a = s.array || [];
    if (a.join(',') === '1,2,3,4,5,6') return i;
  }
  return frames.length - 1;
}

