  if (step === 1) {
    for (i = 0; i < frames.length; i++) {
      if (frames[i].kind === 'shift') return i;
    }
    return Math.min(3, frames.length - 1);
  }
  if (step === 2) {
    for (i = 0; i < frames.length; i++) {
      s = frames[i].state || {}; a = s.array || [];
      if (s.sortedK >= 3 && !s.keyIndex && a.slice(0, 3).join(',') === '2,4,5') return i;
    }
    return Math.floor(frames.length / 2);
