function makeWorkerSource() {
  return `
self.onmessage = function(e) {
  const source = e.data.source;
  const input = e.data.input;
  let A = [null].concat(input.slice());
  const original = input.slice();
  let sortedK = 0;
  let keyIndex = null;
  let compareIndices = [];
  let arrows = [];
  const frames = [];
  let ops = 0;
  const maxOps = 5000;
  const maxFrames = 1200;
  const start = Date.now();

  function clone(obj) { return JSON.parse(JSON.stringify(obj)); }
  function state() {
    return { array: A.slice(1), sortedK: sortedK, keyIndex: keyIndex, compare: compareIndices.slice(), arrows: clone(arrows), input: original.slice() };
  }
  function push(kind, indices, message) {
    ops++;
    if (ops > maxOps) throw new Error('Operation cap reached. Is the loop making progress?');
    if (frames.length >= maxFrames) throw new Error('Frame cap reached. Try fewer operations.');
    if (Date.now() - start > 1600) throw new Error('Time limit reached.');
    frames.push({ kind: kind, state: state(), indices: (indices || []).slice(), message: String(message || kind) });
  }
  function checkIndex(i) {
    if (!Number.isInteger(i) || i < 1 || i >= A.length) throw new Error('Index ' + i + ' is out of range 1..' + (A.length - 1));
  }
  function n() {
    push('n', [], 'n() → ' + (A.length - 1));
    return A.length - 1;
  }
  function compare(i, j) {
    checkIndex(i); checkIndex(j);
    compareIndices = [i, j];
    const result = A[i] > A[j];
    push('compare', [i, j], 'compare A[' + i + ']=' + A[i] + ' with A[' + j + ']=' + A[j] + ' → ' + result);
    return result;
  }
  function shift(i) {
    checkIndex(i);
    if (i <= 1) throw new Error('shift(1) cannot move left.');
    const before = A[i];
    const tmp = A[i - 1];
    A[i - 1] = A[i];
    A[i] = tmp;
    if (keyIndex === i) keyIndex = i - 1;
    compareIndices = [i - 1, i];
    arrows.push({ from: i, to: i - 1 });
    push('shift', [i - 1, i], 'shift key ' + before + ' left from position ' + i + ' to ' + (i - 1));
    return i - 1;
  }
  function markKey(i) {
    checkIndex(i);
    if (keyIndex === null || i > sortedK + 1) arrows = [];
    keyIndex = i;
    compareIndices = [];
    push('markKey', [i], 'mark A[' + i + ']=' + A[i] + ' as the current key');
  }
  function markSortedPrefix(k) {
    if (!Number.isInteger(k) || k < 0 || k >= A.length) throw new Error('Prefix length ' + k + ' is out of range.');
    sortedK = k;
    keyIndex = null;
    compareIndices = [];
    arrows = [];
    push('markSortedPrefix', [], 'cells 1 through ' + k + ' are now the sorted prefix');
  }
  function note(text) {
    push('note', [], text);
  }

  function sortedPrefixBadIndex(arr, k) {
    for (let i = 1; i < k; i++) if (arr[i - 1] > arr[i]) return [i, i + 1];
    return [];
  }
  function sameMultiset(a, b) {
    const sa = a.slice().sort((x,y)=>x-y).join(',');
    const sb = b.slice().sort((x,y)=>x-y).join(',');
    return sa === sb;
  }
  function finalCheck() {
    let bad = sortedPrefixBadIndex(A.slice(1), A.length - 1);
    if (bad.length) return { ok: false, indices: bad, message: 'Wrong answer: the final array is not in nondecreasing order.' };
    if (!sameMultiset(original, A.slice(1))) return { ok: false, indices: [], message: 'Wrong answer: the final values do not preserve the original multiset.' };
    for (let f of frames) {
      if (f.kind === 'markSortedPrefix') {
        let b = sortedPrefixBadIndex(f.state.array, f.state.sortedK);
        if (b.length) return { ok: false, indices: b, message: 'Wrong answer: a completed prefix was marked sorted before it was actually sorted.' };
      }
    }
    return { ok: true, indices: [], message: 'Correct: every pass leaves a longer sorted prefix, and the final array is sorted.' };
  }

  try {
    const api = Object.freeze({ n, compare, shift, markKey, markSortedPrefix, note });
    const runner = new Function('api',
      '"use strict"; const {n,compare,shift,markKey,markSortedPrefix,note}=api;\\n' +
      source +
      '\\nif (typeof insertionSort !== "function") throw new Error("Missing entry point: define function insertionSort().");\\ninsertionSort();'
    );
    runner(api);
    const result = finalCheck();
    if (!result.ok) {
      compareIndices = result.indices;
      frames.push({ kind: 'wrong', state: state(), indices: result.indices, message: result.message });
    } else {
      compareIndices = [];
      keyIndex = null;
      sortedK = A.length - 1;
      arrows = [];
      frames.push({ kind: 'success', state: state(), indices: [], message: result.message });
    }
    self.postMessage({ ok: result.ok, frames: frames, message: result.message });
  } catch (err) {
    frames.push({ kind: 'error', state: state(), indices: compareIndices.slice(), message: 'Error: ' + (err && err.message ? err.message : err) });
    self.postMessage({ ok: false, error: true, frames: frames, message: 'Error: ' + (err && err.message ? err.message : err) });
  }
};`;
}

function runStudentCode() {
  stopPlayback();
  var source = document.getElementById('insertionSortCodeCode').value;
  var input;
  try {
    input = parseInputArray(document.getElementById('insertionSortCodeInput').value);
  } catch (e) {
    frames = [{
      kind: 'error',
      state: { array: [5, 2, 4, 6, 1, 3], sortedK: 0, keyIndex: null, compare: [], arrows: [], input: [5, 2, 4, 6, 1, 3] },
      indices: [],
      message: 'Error: ' + e.message
    }];
