// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 1240, 360);
draw.node.setAttribute('preserveAspectRatio', 'xMidYMid meet');

var panelMode = 'allPanels';
var currentStep = 0;
var fontFam = 'Times New Roman, Times, serif';
var grayFill = '#c9c9c9';
var arrowGray = '#8f8f8f';

var cellW = 58;
var cellH = 52;
var arrX = 70;
var arrY = 38;

var panels = [
  {
    id: 'panelA', label: '(a)', col: 0, row: 0,
    values: [5, 2, 4, 6, 1, 3], gray: [1], key: 2,
    keyMove: { from: 2, to: 1 }, shifts: [{ from: 1, to: 2 }],
    title: 'Panel (a): insert 2',
    body: 'The black cell is the key 2 before it is inserted. The gray 5 is the local trace cell that shifts one position right to make room.'
  },
  {
    id: 'panelB', label: '(b)', col: 1, row: 0,
    values: [2, 5, 4, 6, 1, 3], gray: [1, 2], key: 3,
    keyMove: { from: 3, to: 2 }, shifts: [{ from: 2, to: 3 }],
    title: 'Panel (b): insert 4',
    body: 'The key 4 moves left between 2 and 5. Gray marks the source panel’s comparison/shift context for this insertion, not a general rule that every sorted-prefix cell must be gray.'
  },
  {
    id: 'panelC', label: '(c)', col: 2, row: 0,
    values: [2, 4, 5, 6, 1, 3], gray: [3], key: 4,
    keyMove: null, selfKey: 4, shifts: [],
    title: 'Panel (c): examine 5 before 6',
    body: 'Only cell 3 is gray here: the value 5 is the examined value that shows the key 6 can remain in place. Cells 1 and 2 are already ordered, but the source figure does not shade them in this panel.'
  },
  {
    id: 'panelD', label: '(d)', col: 0, row: 1,
    values: [2, 4, 5, 6, 1, 3], gray: [1, 2, 3, 4], key: 5,
    keyMove: { from: 5, to: 1 }, shifts: [{ from: 1, to: 2 }, { from: 2, to: 3 }, { from: 3, to: 4 }, { from: 4, to: 5 }],
    title: 'Panel (d): insert 1',
    body: 'The key 1 moves all the way to the front. The gray cells are the four values that shift right as the key passes them.'
  },
  {
    id: 'panelE', label: '(e)', col: 1, row: 1,
    values: [1, 2, 4, 5, 6, 3], gray: [2, 3, 4, 5], key: 6,
    keyMove: { from: 6, to: 3 }, shifts: [{ from: 3, to: 4 }, { from: 4, to: 5 }, { from: 5, to: 6 }],
    title: 'Panel (e): insert 3',
    body: 'The key 3 moves left into the gap between 2 and 4. The source gray span is exactly cells 2 through 5; cell 1 and the final cell 6 are not gray.'
  },
  {
    id: 'panelF', label: '(f)', col: 2, row: 1,
    values: [1, 2, 3, 4, 5, 6], gray: [], key: null,
    keyMove: null, shifts: [],
    title: 'Panel (f): sorted result',
    body: 'The array is sorted, but no gray trace remains and there is no black key cell. Completion is shown by the final order of the values, not by shading every cell.'
  }
];

var demoSteps = [
  {
    title: 'Full textbook figure',
    narration: 'The default view shows all six source snapshots. Black marks the key being inserted, while gray marks the specific cells examined or shifted in that panel rather than the entire sorted prefix.',
    state: { panelNavigator: 'allPanels' }
  },
  {
    title: 'Panel (a): insert 2',
    narration: 'The key 2 moves left ahead of 5, and the gray 5 is the element shifted right to make room.',
    state: { panelNavigator: 'panelA' }
  },
  {
    title: 'Panel (b): insert 4',
    narration: 'The key 4 moves between 2 and 5. The gray cells show the source-highlighted comparison or shift context for this insertion, not every sorted cell by rule.',
    state: { panelNavigator: 'panelB' }
  },
  {
    title: 'Panel (c): examine 5 before 6',
    narration: 'Only cell 3 is gray because 5 is the examined value that confirms key 6 can stay where it is. Cells 1 and 2 are already ordered but are not gray here.',
    state: { panelNavigator: 'panelC' }
  },
  {
    title: 'Panel (d): insert 1',
    narration: 'The key 1 moves all the way to the front. The gray run marks the values shifted right as space opens for the key.',
    state: { panelNavigator: 'panelD' }
  },
  {
    title: 'Panel (e): insert 3',
    narration: 'The key 3 moves into the middle of the sorted portion. The source gray highlight is limited to cells 2 through 5, so cell 1 and the final cell 6 remain white.',
    state: { panelNavigator: 'panelE' }
  },
  {
    title: 'Panel (f): sorted result',
    narration: 'The final panel shows the sorted array with no gray cells and no key cell. Completion is shown by the values themselves, not by shading the whole array.',
    state: { panelNavigator: 'panelF' }
  }
];

function panelX(col) {
  return [0, 410, 820][col];
}

function panelY(row) {
  return row === 0 ? 0 : 166;
}

function addInteractive(el, tip, title, body) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup(title, body); });
}

function arrowHead(g, x, y, color, size) {
  size = size || 16;
  g.polygon([[x, y - 2], [x - size * 0.72, y + size * 1.55], [x + size * 0.72, y + size * 1.28]])
    .fill(color)
    .stroke('none');
}

function drawMoveArrow(g, from, to, color, deep, width) {
  var sx = arrX + (from - 0.5) * cellW;
  var ex = arrX + (to - 0.5) * cellW;
  var y = arrY + cellH + 1;
  var d = deep || 58;
  var path = 'M ' + sx + ' ' + y +
    ' C ' + sx + ' ' + (y + d) + ' ' + ex + ' ' + (y + d) + ' ' + ex + ' ' + y;
  var p = g.path(path).fill('none').stroke({
    color: color,
    width: width || 4.2,
    linecap: 'round',
    linejoin: 'round'
  });
  arrowHead(g, ex, y, color, color === '#000000' ? 18 : 17);
  addInteractive(
    p,
    color === '#000000' ? 'Black arrow: movement of the key' : 'Gray arrow: a shifted or examined value',
    'Curved insertion arrow',
    color === '#000000'
      ? 'The black arrow follows the key as insertion sort moves it left into its correct position.'
      : 'A gray arrow shows one of the local trace movements or comparisons drawn in the source panel.'
  );
}

function drawSelfArrow(g, idx) {
  var cx = arrX + (idx - 0.5) * cellW;
  var y = arrY + cellH + 1;
  var path = 'M ' + (cx + 12) + ' ' + y +
    ' C ' + (cx + 15) + ' ' + (y + 82) + ' ' + (cx - 15) + ' ' + (y + 82) + ' ' + (cx - 15) + ' ' + y;
  var p = g.path(path).fill('none').stroke({
    color: '#000000',
    width: 4.2,
    linecap: 'round',
    linejoin: 'round'
  });
  arrowHead(g, cx - 15, y, '#000000', 18);
  addInteractive(
    p,
    'Black loop: key remains in its current position',
    'No shift needed',
    'The key is already greater than the examined value, so insertion sort leaves it in place.'
  );
}

function drawPanel(p, tx, ty, scale) {
  var g = draw.group();
  g.transform({ translateX: tx, translateY: ty, scale: scale || 1 });

  g.text(p.label)
    .font({ family: fontFam, size: 43, anchor: 'middle' })
    .fill('#000')
    .center(25, arrY + 30);

  for (var i = 1; i <= 6; i++) {
    g.text(String(i))
      .font({ family: fontFam, size: 38, anchor: 'middle' })
      .fill('#000')
      .center(arrX + (i - 0.5) * cellW, 18);
  }

  var arrows = g.group();
  for (var s = 0; s < p.shifts.length; s++) {
    drawMoveArrow(arrows, p.shifts[s].from, p.shifts[s].to, arrowGray, 58, 3.9);
  }
  if (p.keyMove) {
    var span = Math.abs(p.keyMove.from - p.keyMove.to);
    drawMoveArrow(arrows, p.keyMove.from, p.keyMove.to, '#000000', span > 2 ? 94 : 75, 4.4);
  }
  if (p.selfKey) {
    drawSelfArrow(arrows, p.selfKey);
  }

  var graySet = {};
  for (var j = 0; j < p.gray.length; j++) graySet[p.gray[j]] = true;

  for (var k = 1; k <= 6; k++) {
    var isKey = p.key === k;
    var fill = isKey ? '#000000' : (graySet[k] ? grayFill : '#ffffff');
    var r = g.rect(cellW, cellH)
      .move(arrX + (k - 1) * cellW, arrY)
      .fill(fill)
      .stroke({ color: '#000000', width: 2.25 });

    var role = isKey ? 'current black key' : (graySet[k] ? 'source-panel gray trace cell' : 'unhighlighted white cell');
    addInteractive(
      r,
      p.label + ' A[' + k + '] = ' + p.values[k - 1] + ' — ' + role,
      p.title,
      p.body
    );

    g.text(String(p.values[k - 1]))
      .font({ family: fontFam, size: 42, anchor: 'middle' })
      .fill(isKey ? '#ffffff' : '#000000')
      .center(arrX + (k - 0.5) * cellW, arrY + cellH / 2 + 2);
  }

  return g;
}

function drawAll() {
  draw.clear();
  draw.rect(1240, 360).fill('#ffffff');

  if (panelMode === 'allPanels') {
    for (var i = 0; i < panels.length; i++) {
      drawPanel(panels[i], panelX(panels[i].col), panelY(panels[i].row), 1);
    }
  } else {
    for (var j = 0; j < panels.length; j++) {
      if (panels[j].id === panelMode) {
        drawPanel(panels[j], 260, 32, 1.65);
        break;
      }
    }
  }
}

window.update_panelNavigator = function (value) {
  panelMode = value;
  drawAll();
};

function applyStep(idx) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, idx));
  var step = demoSteps[currentStep];
  panelMode = step.state.panelNavigator;

  var sel = document.getElementById('panelNavigatorInput');
  if (sel) sel.value = panelMode;

  var narration = document.getElementById('demoNarration');
  if (narration) narration.textContent = step.title + ': ' + step.narration;

  var stepLabel = document.getElementById('stepLabel');
  if (stepLabel) stepLabel.textContent = 'Step ' + (currentStep + 1) + ' of ' + demoSteps.length;

  drawAll();
}

window.prevStep = function () {
  applyStep(currentStep - 1);
};

window.nextStep = function () {
  applyStep(currentStep + 1);
};

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

